    // configured base URL, static origins, plugin origins, and BETTER_AUTH_TRUSTED_ORIGINS.
    const configuredOrigins = authContext.options.trustedOrigins;
    const mergedOrigins = typeof configuredOrigins === 'function'
        ? await configuredOrigins(context.req.raw)
        : (configuredOrigins ?? []);
    const requestAuthContext = Object.create(authContext);
    requestAuthContext.trustedOrigins = [
        ...authContext.trustedOrigins,
        ...mergedOrigins.filter((origin) => typeof origin === 'string' && Boolean(origin)),
    ];
    const trustedByAuth = requestAuthContext.isTrustedOrigin(source, {
        allowRelativePaths: false,
    });
    if (!trustedByAuth) {
        return invalidCsrfOrigin(context);
    }
}

/** A cookie-bearing write whose origin is neither the application's own nor a trusted one. */
function invalidCsrfOrigin(context) {
    return apiErrorHandler(new ApiError({
        status: 'PERMISSION_DENIED',
        reason: 'INVALID_CSRF_ORIGIN',
        domain: 'authentication',
        message: 'The request origin is not trusted for a cookie-authenticated write.',
    }), context);
}

export async function createTestApp(options) {
    const { createServer, server: serverOptions = {}, ...configOptions } = options;
    const config = await createTestAppConfig(configOptions);
    let server;
    try {
        server = await createServer({
            viteDevUrl: false,
            ...serverOptions,
            configPath: config.path,
            env: {
                APP_STORAGE_DIR: path.join(config.directory, 'storage'),
                ...serverOptions.env,
            },
        });
    }
    catch (error) {
        await config.dispose();
        throw error;
    }
    const { application } = server;
    const database = application.container.resolve(databaseManagerToken);
    const apiRoot = `http://localhost${trimTrailingSlash(application.publicBasePath)}/api`;
    const fetch = (request) => server.fetch(request);
    return {
        server,
        application,
        publicBasePath: application.publicBasePath,
        fetch,
        database,
        connection: database.connection(),
        config,
        request: async (target, init) => fetch(new Request(target.startsWith('/') ? `${apiRoot}${target}` : target, init)),
        close: async () => {
            try {
                await server.close();
            }
            finally {
                await config.dispose();
            }
        },
    };

## An application on test databases

```ts
import { createTestApp } from '@nocobase/app-testing/server';
import { createStandaloneServer } from '../../server/standalone.ts';

const app = await createTestApp({ createServer: createStandaloneServer });
try {
  const response = await app.request('/healthz'); // <publicBasePath>/api/healthz
} finally {
  await app.close(); // stops it, drops its databases, removes its files
}
```

`createTestApp()` provisions one database per connection in `connections` (`['main']` by default) and writes an application configuration file naming them, which the application loads through `configPath` exactly as it loads `config.yml`. A connection not named keeps what the application configures, which is how an `external` connection keeps the database it reads but does not own. `config` adds further sections to the same file, such as `{ users: { initialAdmin: … } }`. The application installs itself on start — its own and its plugins' migrations and seeds on every provisioned connection — unless `install: false`. Its storage goes to a temporary directory, so applications started side by side share no queue or jobs state.

The application has to load the configuration file it is given, as the application templates' `server/config.ts` does with `context.configPath ?? context.environment.APP_CONFIG_FILE`.

To act as a signed-in user, sign in through the application with `signIn()` from `@nocobase/app-plugin-authentication/testing`; a test application qualifies as its target.

```ts
import {
  DEFAULT_ADMIN_CREDENTIALS,
  signIn,
} from '@nocobase/app-plugin-authentication/testing';

const admin = await signIn(app, DEFAULT_ADMIN_CREDENTIALS);
const users = await admin.fetch('/users');
```

## Testing through the whole application

To check a route's authentication and permission boundaries as a user meets them, start the application itself on test databases with `@nocobase/app-testing/server` and sign in through its own sign-in route with `@nocobase/app-plugin-authentication/testing`:

```ts
import {
  DEFAULT_ADMIN_CREDENTIALS,
  signIn,
} from '@nocobase/app-plugin-authentication/testing';
import { createAppTest } from '@nocobase/app-testing/server';
import { createStandaloneServer } from '../../server/standalone.ts';

const test = createAppTest({ createServer: createStandaloneServer });

test('lists orders for an administrator only', async ({ testApp, request }) => {
  expect((await request('/orders')).status).toBe(401);
  const admin = await signIn(testApp, DEFAULT_ADMIN_CREDENTIALS);
  expect((await admin.fetch('/orders')).status).toBe(200);
});
```

The application starts as `pnpm start` starts it and installs its migrations and seeds on start; one application serves the test file. A user other than the administrator is one a seed of the application created, signed in the same way.

